"""Individually authored task/state decisions for the final C8 review.

These are documentary design inputs. They never execute product commands.
Each entry describes a distinct task, including its recovery and limits.
"""


def screen(state, guard, sequence, readonly, success, empty, recovery, layout, reconstruction):
    return dict(state=state, guard=guard, sequence=sequence, readonly=readonly,
                success=success, empty=empty, recovery=recovery, layout=layout,
                reconstruction=reconstruction)


